#[test]
fn meta_filter_matches_block_list_in_bare_frontmatter() {
    setup();

    // Regression: bare frontmatter with a block-style YAML list (`depends:` /
    // `  - foo`) used to lose the indented list items because the wrapper
    // stripped space-prefixed lines before fencing. As a result
    // `iwe find --meta depends=foo` returned no matches for these documents.
    let graph = Graph::import(
        &from_indoc(indoc! {"
            title: Foo
            depends:
              - foo
              - bar

            # Body
            "}),
        bare_options(),
        None,
    );

    let opts = liwe::find::FindOptions {
        metadata_filters: vec![("depends".to_string(), "foo".to_string())],
        ..Default::default()
    };
    let hits = liwe::find::Find::new(&graph).search(&opts);
    assert!(
        !hits.is_empty(),
        "expected bare-frontmatter doc with `depends: [- foo]` to match `--meta depends=foo`"
    );
}

